*** Add File: src/cli.ts
+type InputTask = {
+  id?: unknown;
+  duration?: unknown;
+  dependsOn?: unknown;
+};
+
+type Task = {
+  id: string;
+  duration: number;
+  dependsOn: string[];
+};
+
+function fail(message: string): never {
+  console.error(message);
+  process.exit(1);
+}
+
+function parseTasks(value: unknown): Task[] {
+  if (!value || typeof value !== "object" || !Array.isArray((value as { tasks?: unknown }).tasks)) {
+    fail("Invalid input: tasks must be an array.");
+  }
+
+  const rawTasks = (value as { tasks: unknown[] }).tasks;
+  const tasks: Task[] = [];
+  const ids = new Set<string>();
+
+  for (const raw of rawTasks) {
+    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
+      fail("Invalid task: each task must be an object.");
+    }
+    const task = raw as InputTask;
+    if (typeof task.id !== "string" || task.id.length === 0) {
+      fail("Invalid task: id must be a non-empty string.");
+    }
+    if (ids.has(task.id)) fail(`Invalid task: duplicate id '${task.id}'.`);
+    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
+      fail(`Invalid task '${task.id}': duration must be a finite non-negative number.`);
+    }
+    const dependsOn = task.dependsOn === undefined ? [] : task.dependsOn;
+    if (!Array.isArray(dependsOn) || !dependsOn.every((dependency) => typeof dependency === "string")) {
+      fail(`Invalid task '${task.id}': dependsOn must be an array of strings.`);
+    }
+    if (new Set(dependsOn).size !== dependsOn.length) {
+      fail(`Invalid task '${task.id}': dependsOn must contain unique ids.`);
+    }
+    if (dependsOn.includes(task.id)) fail(`Invalid task '${task.id}': it cannot depend on itself.`);
+    ids.add(task.id);
+    tasks.push({ id: task.id, duration: task.duration, dependsOn });
+  }
+
+  for (const task of tasks) {
+    for (const dependency of task.dependsOn) {
+      if (!ids.has(dependency)) fail(`Invalid task '${task.id}': unknown dependency '${dependency}'.`);
+    }
+  }
+  return tasks;
+}
+
+function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
+  const state = new Map<string, number>();
+  const stack: string[] = [];
+  const visit = (id: string): string[] | undefined => {
+    state.set(id, 1);
+    stack.push(id);
+    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
+      if (state.get(dependency) === 1) return [...stack.slice(stack.indexOf(dependency)), dependency];
+      if (!state.has(dependency)) {
+        const cycle = visit(dependency);
+        if (cycle) return cycle;
+      }
+    }
+    stack.pop();
+    state.set(id, 2);
+  };
+  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
+    if (!state.has(task.id)) {
+      const cycle = visit(task.id);
+      if (cycle) return cycle;
+    }
+  }
+}
+
+function plan(tasks: Task[]) {
+  const byId = new Map(tasks.map((task) => [task.id, task]));
+  const cycle = findCycle(tasks, byId);
+  if (cycle) fail(`Cycle detected: ${cycle.join(" -> ")}`);
+
+  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
+  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
+  for (const task of tasks) for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
+
+  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
+  const order: string[] = [];
+  while (ready.length > 0) {
+    const id = ready.shift()!;
+    order.push(id);
+    for (const dependent of dependents.get(id)!.sort()) {
+      const count = remaining.get(dependent)! - 1;
+      remaining.set(dependent, count);
+      if (count === 0) {
+        ready.push(dependent);
+        ready.sort();
+      }
+    }
+  }
+
+  const earliest: Record<string, { start: number; finish: number }> = {};
+  const layers: string[][] = [];
+  const paths = new Map<string, string[]>();
+  for (const id of order) {
+    const task = byId.get(id)!;
+    const start = task.dependsOn.reduce((maximum, dependency) => Math.max(maximum, earliest[dependency].finish), 0);
+    earliest[id] = { start, finish: start + task.duration };
+    const layer = task.dependsOn.reduce((maximum, dependency) => Math.max(maximum, paths.get(dependency)!.length), 0);
+    (layers[layer] ??= []).push(id);
+
+    const candidates = task.dependsOn.map((dependency) => paths.get(dependency)!);
+    candidates.sort((left, right) => left.join("\u0000").localeCompare(right.join("\u0000")));
+    paths.set(id, [...(candidates[0] ?? []), id]);
+  }
+  for (const layer of layers) layer.sort();
+
+  const totalDuration = order.reduce((maximum, id) => Math.max(maximum, earliest[id].finish), 0);
+  const endings = order.filter((id) => earliest[id].finish === totalDuration).map((id) => paths.get(id)!);
+  endings.sort((left, right) => left.join("\u0000").localeCompare(right.join("\u0000")));
+  return { order, layers, earliest, totalDuration, criticalPath: endings[0] ?? [] };
+}
+
+if (process.argv.length !== 4 || process.argv[2] !== "plan") {
+  fail("Usage: bun run src/cli.ts plan INPUT.json");
+}
+
+let input: unknown;
+try {
+  input = JSON.parse(await Bun.file(process.argv[3]).text());
+} catch (error) {
+  fail(`Unable to read valid JSON: ${error instanceof Error ? error.message : String(error)}`);
+}
+console.log(JSON.stringify(plan(parseTasks(input))));
*** Add File: README.md
+# Dependency Planner
+
+A dependency-free Bun TypeScript CLI that validates a task graph and computes a deterministic execution plan.
+
+## Usage
+
+```sh
+bun run src/cli.ts plan INPUT.json
+```
+
+Input must be JSON with a `tasks` array. Each task has a unique non-empty string `id`, a finite non-negative numeric `duration`, and optional unique string `dependsOn` ids.
+
+The command prints one JSON object containing a lexicographic topological `order`, concurrent `layers`, unlimited-parallelism `earliest` timings, `totalDuration`, and a deterministic `criticalPath`. Invalid input and cycles exit non-zero with an explanatory message on stderr.
*** End Patch

