function plan(tasks: Task[]) {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const cycle = findCycle(tasks, byId);
  if (cycle) fail(`Cycle detected: ${cycle.join(" -> ")}`);

  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
  for (const task of tasks) for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of dependents.get(id)!.sort()) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) {
        ready.push(dependent);
        ready.sort();
      }
    }
  }

  const earliest: Record<string, { start: number; finish: number }> = {};
  const layers: string[][] = [];
  const paths = new Map<string, string[]>();
  for (const id of order) {
    const task = byId.get(id)!;
    const start = task.dependsOn.reduce((maximum, dependency) => Math.max(maximum, earliest[dependency].finish), 0);
    earliest[id] = { start, finish: start + task.duration };
    const layer = task.dependsOn.reduce((maximum, dependency) => Math.max(maximum, paths.get(dependency)!.length), 0);
    (layers[layer] ??= []).push(id);

    const candidates = task.dependsOn.map((dependency) => paths.get(dependency)!);
    candidates.sort((left, right) => left.join("\u0000").localeCompare(right.join("\u0000")));
    paths.set(id, [...(candidates[0] ?? []), id]);
  }
  for (const layer of layers) layer.sort();

  const totalDuration = order.reduce((maximum, id) => Math.max(maximum, earliest[id].finish), 0);
  const endings = order.filter((id) => earliest[id].finish === totalDuration).map((id) => paths.get(id)!);
  endings.sort((left, right) => left.join("\u0000").localeCompare(right.join("\u0000")));
  return { order, layers, earliest, totalDuration, criticalPath: endings[0] ?? [] };
}

if (process.argv.length !== 4 || process.argv[2] !== "plan") {
  fail("Usage: bun run src/cli.ts plan INPUT.json");
}

let input: unknown;
try {
  input = JSON.parse(await Bun.file(process.argv[3]).text());
} catch (error) {
  fail(`Unable to read valid JSON: ${error instanceof Error ? error.message : String(error)}`);
}
console.log(JSON.stringify(plan(parseTasks(input))));

